using System.Text.Json;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;
using Shop.Modules.Credit;
using Shop.SharedKernel;
using Xunit;
namespace Shop.Tests;
public sealed class CreditUpfrontTests
{
    private static string Id()=>Guid.NewGuid().ToString("N");private static string V=>Convert.ToBase64String(new byte[8]);
    private static CreditUpfrontInput Input()=>new("ConfirmReceipt",V,V,null,"SYNTHETIC-REFERENCE","Private sample 🎮",DateTimeOffset.UtcNow,true);
    [Fact]public void CommittedCorrectionNeedsItsOwnAcknowledgementExistingVersionAndPrivateReason(){var x=Input()with{Version=V,AcknowledgedCommittedOrder=true};CreditUpfrontRules.Input(x);foreach(var invalid in new[]{x with{Version=null},x with{Note=""},x with{AcknowledgedClosedOrder=true},x with{Confirmed=false}})Assert.Throws<BusinessException>(()=>CreditUpfrontRules.Input(invalid));}
    [Fact]public void DefaultFalseCommittedFlagPreservesLegacyCanonicalBodyAndOldOptionalReceipts(){var x=Input();var options=new JsonSerializerOptions(JsonSerializerDefaults.Web);var legacy=JsonSerializer.Serialize(new{x.Action,x.OrderVersion,x.ScheduleVersion,x.Version,x.Reference,x.Note,x.OccurredAt,x.Confirmed,x.AcknowledgedClosedOrder},options);Assert.Equal(legacy,JsonSerializer.Serialize(x,options));Assert.False(JsonSerializer.Deserialize<CreditUpfrontInput>(legacy,options)!.AcknowledgedCommittedOrder);var corrected=JsonSerializer.Serialize(x with{Version=V,AcknowledgedCommittedOrder=true},options);Assert.Contains("\"acknowledgedCommittedOrder\":true",corrected);Assert.NotEqual(legacy,corrected);}
    [Fact]public void AmountComesFromAllNonChequeChargesAndRemainsInt64Exact(){Assert.Equal(30,CreditUpfrontRules.Required(100,[30,40]));Assert.Equal(0,CreditUpfrontRules.Required(100,[100]));Assert.Equal(long.MaxValue-1,CreditUpfrontRules.Required(long.MaxValue,[1]));Assert.Equal("9223372036854775806",CreditUpfrontRules.Rial(CreditUpfrontRules.Required(long.MaxValue,[1])));Assert.Throws<BusinessException>(()=>CreditUpfrontRules.Required(long.MaxValue,[long.MaxValue,1]));Assert.Throws<BusinessException>(()=>CreditUpfrontRules.Required(100,[101]));Assert.Throws<BusinessException>(()=>CreditUpfrontRules.Required(100,[0]));}
    [Theory][InlineData(null,"ConfirmReceipt",10,"ReceiptConfirmed")][InlineData(null,"ConfirmNoUpfrontDue",0,"NoUpfrontDue")][InlineData("ReceiptConfirmed","RevokeConfirmation",10,"Revoked")][InlineData("NoUpfrontDue","RevokeConfirmation",0,"Revoked")][InlineData("Revoked","ConfirmReceipt",10,"ReceiptConfirmed")]
    public void ExplicitStatesNeverMeanBankVerificationOrCashPaid(string? prior,string action,long amount,string state){Assert.Equal(state,CreditUpfrontRules.Next(prior,action,amount));Assert.Equal(state=="ReceiptConfirmed"?amount:0,CreditUpfrontRules.Acknowledged(state,amount));}
    [Fact]public void ZeroIsExplicitAndAnActiveConfirmationCannotBeCountedTwice(){foreach(var x in new[]{(state:(string?)null,action:"ConfirmReceipt",amount:0L),(state:(string?)null,action:"ConfirmNoUpfrontDue",amount:1L),(state:(string?)null,action:"RevokeConfirmation",amount:1L),(state:(string?)"ReceiptConfirmed",action:"ConfirmReceipt",amount:1L),(state:(string?)"Revoked",action:"RevokeConfirmation",amount:1L)})Assert.Throws<BusinessException>(()=>CreditUpfrontRules.Next(x.state,x.action,x.amount));}
    [Fact]public void InputsRequireVersionsExplicitConfirmationAndPrivateReferenceForPositiveReceipts(){var good=Input();CreditUpfrontRules.Input(good);CreditUpfrontRules.Input(good with{Action="ConfirmNoUpfrontDue",Reference=""});foreach(var bad in new[]{good with{Confirmed=false},good with{Reference=""},good with{OrderVersion="bad"},good with{Action="Paid"},good with{OccurredAt=good.OccurredAt.ToOffset(TimeSpan.FromHours(3.5))},good with{Action="RevokeConfirmation",Reference="",Note="reason"},good with{Action="ConfirmNoUpfrontDue"},good with{AcknowledgedClosedOrder=true},good with{Note="\ud800"},good with{Reference="\u202econcealed"}})Assert.Throws<BusinessException>(()=>CreditUpfrontRules.Input(bad));Assert.Throws<JsonException>(()=>JsonSerializer.Deserialize<CreditUpfrontInput>("{\"action\":\"ConfirmReceipt\",\"amountRial\":\"1\"}"));}
    [Fact]public void DedicatedSealsCannotMoveAcrossOrderPrincipalRevisionOrPurpose(){var p=new DataProtectionCreditUpfrontProtection(new EphemeralDataProtectionProvider());var order=Id();var revision=Id();var bytes=p.Protect("event","OWNER",order,revision,"Synthetic private upfront evidence");Assert.Equal("Synthetic private upfront evidence",p.Unprotect("event","OWNER",order,revision,bytes));Assert.Throws<BusinessException>(()=>p.Unprotect("receipt","OWNER",order,revision,bytes));Assert.Throws<BusinessException>(()=>p.Unprotect("event","OTHER",order,revision,bytes));Assert.Throws<BusinessException>(()=>p.Unprotect("event","OWNER",Id(),revision,bytes));Assert.Throws<BusinessException>(()=>p.Unprotect("event","OWNER",order,Id(),bytes));bytes[^1]^=1;Assert.Throws<BusinessException>(()=>p.Unprotect("event","OWNER",order,revision,bytes));Assert.Throws<BusinessException>(()=>p.Protect("arbitrary","OWNER",order,revision,"x"));}
    [Fact]public void ImmutableUpfrontRowsFailBeforeAConnectionIsOpened(){using var db=new CreditDbContext(new DbContextOptionsBuilder<CreditDbContext>().UseSqlServer("Server=unused;Database=unused").Options);var row=new CreditUpfrontConfirmation();db.Attach(row);db.Remove(row);Assert.Equal("credit_upfront_history_immutable",Assert.Throws<BusinessException>(()=>db.SaveChanges()).Code);}
}
